**2. `health_checker.c` core logic:**
```c
// In src/health_checker.c
#include "health_checker.h"
#include "model.h"
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <time.h>

void perform_health_check(ServiceNode *node) {
    if (!node || !node->service_ip) return;

    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) { return; }

    struct sockaddr_in serv_addr;
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(node->health_check_port);
    inet_pton(AF_INET, node->service_ip, &serv_addr.sin_addr);

    if (connect(sock, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        node->status = UNHEALTHY;
    } else {
        node->status = HEALTHY;
    }

    node->last_check_timestamp = time(NULL);
    close(sock);
}
```

